import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import vm from "node:vm";

const args = process.argv.slice(2);
const option = name => args[args.indexOf(name) + 1];
const values = ["GPIO_DIR_MODE_IN", "GPIO_DIR_MODE_OUT"];
const instances = ["LED1", "LED2"].map((name, index) => {
  let direction = values[0];
  return {
    $name: name,
    gpioPin: { $assign: `GPIO${12 + index}` },
    get direction() { return direction; },
    set direction(value) {
      if (!values.includes(value)) throw new Error("Invalid GPIO direction");
      direction = value;
    }
  };
});
const module = { displayName: "GPIO", $static: { $name: "staticInstance" }, $instances: instances,
  $configByName: { direction: { displayName: "Direction", options: values.map(name => ({ name })) } } };
const source = await readFile(option("--script"), "utf8");
if (source.includes("WAIT")) await new Promise(resolve => setTimeout(resolve, 1300));
try {
  const context = vm.createContext({ system: { modules: { "/driverlib/gpio.js": module } }, console });
  vm.runInContext(source, context);
  vm.runInContext(await readFile(option("--dependentScript"), "utf8"), context);
  if (instances[0].gpioPin.$assign === instances[1].gpioPin.$assign) throw new Error("Pin conflict: GPIO already assigned");
  await writeFile(path.join(option("--output"), "board.c"), "generated by the fixture engine");
  console.error("0 error(s), 0 warning(s)");
} catch (error) {
  console.error(error.message);
  process.exitCode = 1;
}
